import { describe, it, expect } from 'vitest'
import {
  validateEmailDetailed,
  isDisposableEmail,
  normalizeEmail,
  suggestEmailCorrection,
} from '@/src/lib/email-validation'

describe('email-validation.ts — advanced email validation', () => {
  // ─── validateEmailDetailed ─────────────────────────────────────

  describe('validateEmailDetailed', () => {
    it('accepts a standard valid email', () => {
      const result = validateEmailDetailed('user@example.com')
      expect(result.valid).toBe(true)
      expect(result.normalized).toBe('user@example.com')
      expect(result.domain).toBe('example.com')
      expect(result.localPart).toBe('user')
    })

    it('normalizes to lowercase', () => {
      const result = validateEmailDetailed('User@Example.COM')
      expect(result.valid).toBe(true)
      expect(result.normalized).toBe('user@example.com')
    })

    it('trims whitespace', () => {
      const result = validateEmailDetailed('  user@example.com  ')
      expect(result.valid).toBe(true)
      expect(result.normalized).toBe('user@example.com')
    })

    it('accepts email with subdomains', () => {
      const result = validateEmailDetailed('user@mail.sub.example.com')
      expect(result.valid).toBe(true)
      expect(result.domain).toBe('mail.sub.example.com')
    })

    it('accepts email with dots in local part', () => {
      const result = validateEmailDetailed('first.last@example.com')
      expect(result.valid).toBe(true)
    })

    it('accepts email with + tag', () => {
      const result = validateEmailDetailed('user+tag@example.com')
      expect(result.valid).toBe(true)
    })

    it('rejects empty string', () => {
      const result = validateEmailDetailed('')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email is required')
    })

    it('rejects whitespace-only string', () => {
      const result = validateEmailDetailed('   ')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email is required')
    })

    it('rejects email without @ symbol', () => {
      const result = validateEmailDetailed('userexample.com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email must contain @ symbol')
    })

    it('rejects email with empty local part', () => {
      const result = validateEmailDetailed('@example.com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email must contain @ symbol')
    })

    it('rejects local part exceeding 64 characters', () => {
      const longLocal = 'a'.repeat(65)
      const result = validateEmailDetailed(`${longLocal}@example.com`)
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email local part exceeds 64 characters')
    })

    it('accepts local part of exactly 64 characters', () => {
      const local = 'a'.repeat(64)
      const result = validateEmailDetailed(`${local}@example.com`)
      expect(result.valid).toBe(true)
    })

    it('rejects consecutive dots in local part', () => {
      const result = validateEmailDetailed('user..name@example.com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email cannot contain consecutive dots')
    })

    it('rejects local part starting with a dot', () => {
      const result = validateEmailDetailed('.user@example.com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email cannot start or end with a dot')
    })

    it('rejects local part ending with a dot', () => {
      const result = validateEmailDetailed('user.@example.com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email cannot start or end with a dot')
    })

    it('rejects domain without a dot', () => {
      const result = validateEmailDetailed('user@localhost')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email domain must contain a dot')
    })

    it('rejects domain with empty labels (consecutive dots)', () => {
      const result = validateEmailDetailed('user@example..com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email domain has empty labels')
    })

    it('rejects domain label exceeding 63 characters', () => {
      const longLabel = 'a'.repeat(64)
      const result = validateEmailDetailed(`user@${longLabel}.com`)
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email domain label exceeds 63 characters')
    })

    it('rejects domain with invalid characters', () => {
      const result = validateEmailDetailed('user@exam_ple.com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email domain contains invalid characters')
    })

    it('accepts domain with hyphens', () => {
      const result = validateEmailDetailed('user@my-domain.com')
      expect(result.valid).toBe(true)
    })

    it('rejects domain label starting with hyphen', () => {
      const result = validateEmailDetailed('user@-example.com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email domain contains invalid characters')
    })

    it('rejects domain label ending with hyphen', () => {
      const result = validateEmailDetailed('user@example-.com')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email domain contains invalid characters')
    })

    it('rejects single-char TLD', () => {
      const result = validateEmailDetailed('user@example.c')
      expect(result.valid).toBe(false)
      expect(result.error).toBe('Email TLD must be at least 2 characters')
    })

    it('accepts 2-char TLD', () => {
      const result = validateEmailDetailed('user@example.co')
      expect(result.valid).toBe(true)
    })

    it('rejects email exceeding 254 total characters', () => {
      // Build an email that's 255+ characters
      const local = 'a'.repeat(64)
      const domain = 'b'.repeat(63) + '.' + 'c'.repeat(63) + '.' + 'd'.repeat(60) + '.com'
      const email = `${local}@${domain}`
      if (email.length > 254) {
        const result = validateEmailDetailed(email)
        expect(result.valid).toBe(false)
        expect(result.error).toBe('Email exceeds maximum length of 254 characters')
      }
    })
  })

  // ─── isDisposableEmail ─────────────────────────────────────────

  describe('isDisposableEmail', () => {
    it('detects mailinator.com as disposable', () => {
      expect(isDisposableEmail('test@mailinator.com')).toBe(true)
    })

    it('detects guerrillamail.com as disposable', () => {
      expect(isDisposableEmail('test@guerrillamail.com')).toBe(true)
    })

    it('detects yopmail.com as disposable', () => {
      expect(isDisposableEmail('test@yopmail.com')).toBe(true)
    })

    it('detects tempmail.com as disposable', () => {
      expect(isDisposableEmail('test@tempmail.com')).toBe(true)
    })

    it('does not flag gmail.com as disposable', () => {
      expect(isDisposableEmail('user@gmail.com')).toBe(false)
    })

    it('does not flag outlook.com as disposable', () => {
      expect(isDisposableEmail('user@outlook.com')).toBe(false)
    })

    it('returns false for invalid emails', () => {
      expect(isDisposableEmail('not-an-email')).toBe(false)
    })

    it('is case-insensitive', () => {
      expect(isDisposableEmail('Test@MAILINATOR.COM')).toBe(true)
    })
  })

  // ─── normalizeEmail ────────────────────────────────────────────

  describe('normalizeEmail', () => {
    it('lowercases the email', () => {
      expect(normalizeEmail('USER@EXAMPLE.COM')).toBe('user@example.com')
    })

    it('removes dots from Gmail local part', () => {
      expect(normalizeEmail('first.last@gmail.com')).toBe('firstlast@gmail.com')
    })

    it('removes +suffix from Gmail local part', () => {
      expect(normalizeEmail('user+tag@gmail.com')).toBe('user@gmail.com')
    })

    it('normalizes googlemail.com to gmail.com', () => {
      expect(normalizeEmail('user@googlemail.com')).toBe('user@gmail.com')
    })

    it('handles Gmail with both dots and plus', () => {
      expect(normalizeEmail('first.last+tag@gmail.com')).toBe('firstlast@gmail.com')
    })

    it('does NOT remove dots from non-Gmail domains', () => {
      expect(normalizeEmail('first.last@outlook.com')).toBe('first.last@outlook.com')
    })

    it('does NOT remove +suffix from non-Gmail domains', () => {
      expect(normalizeEmail('user+tag@yahoo.com')).toBe('user+tag@yahoo.com')
    })

    it('returns null for invalid emails', () => {
      expect(normalizeEmail('')).toBeNull()
      expect(normalizeEmail('invalid')).toBeNull()
    })
  })

  // ─── suggestEmailCorrection ────────────────────────────────────

  describe('suggestEmailCorrection', () => {
    it('suggests gmail.com for gmial.com', () => {
      expect(suggestEmailCorrection('user@gmial.com')).toBe('user@gmail.com')
    })

    it('suggests gmail.com for gmal.com', () => {
      expect(suggestEmailCorrection('user@gmal.com')).toBe('user@gmail.com')
    })

    it('suggests gmail.com for gamil.com', () => {
      expect(suggestEmailCorrection('user@gamil.com')).toBe('user@gmail.com')
    })

    it('suggests gmail.com for gnail.com', () => {
      expect(suggestEmailCorrection('user@gnail.com')).toBe('user@gmail.com')
    })

    it('suggests gmail.com for gmail.co', () => {
      expect(suggestEmailCorrection('user@gmail.co')).toBe('user@gmail.com')
    })

    it('suggests hotmail.com for hotmal.com', () => {
      expect(suggestEmailCorrection('user@hotmal.com')).toBe('user@hotmail.com')
    })

    it('suggests hotmail.com for hotmial.com', () => {
      expect(suggestEmailCorrection('user@hotmial.com')).toBe('user@hotmail.com')
    })

    it('suggests yahoo.com for yahooo.com', () => {
      expect(suggestEmailCorrection('user@yahooo.com')).toBe('user@yahoo.com')
    })

    it('suggests outlook.com for outlok.com', () => {
      expect(suggestEmailCorrection('user@outlok.com')).toBe('user@outlook.com')
    })

    it('returns null for correct domains', () => {
      expect(suggestEmailCorrection('user@gmail.com')).toBeNull()
      expect(suggestEmailCorrection('user@outlook.com')).toBeNull()
    })

    it('returns null for unknown domains', () => {
      expect(suggestEmailCorrection('user@mycompany.com')).toBeNull()
    })

    it('returns null for invalid emails without domain', () => {
      expect(suggestEmailCorrection('notanemail')).toBeNull()
    })
  })
})

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import {
  calculateBackoffDelay,
  isRetryableError,
  processPaymentWithRetry,
  validatePaymentRequest,
  type PaymentRequest,
  type PaymentResponse,
  type RetryConfig,
} from '@/src/lib/payment-retry'

describe('payment-retry.ts — payment gateway retry', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  // ─── calculateBackoffDelay ─────────────────────────────────────

  describe('calculateBackoffDelay', () => {
    it('returns a delay based on exponential backoff', () => {
      vi.spyOn(Math, 'random').mockReturnValue(0) // no jitter
      const config: RetryConfig = {
        maxRetries: 3,
        baseDelayMs: 1000,
        maxDelayMs: 10000,
        backoffMultiplier: 2,
      }

      // attempt 0: 1000 * 2^0 = 1000, jitter = 0
      expect(calculateBackoffDelay(0, config)).toBe(1000)
      // attempt 1: 1000 * 2^1 = 2000, jitter = 0
      expect(calculateBackoffDelay(1, config)).toBe(2000)
      // attempt 2: 1000 * 2^2 = 4000, jitter = 0
      expect(calculateBackoffDelay(2, config)).toBe(4000)

      vi.restoreAllMocks()
    })

    it('caps delay at maxDelayMs', () => {
      vi.spyOn(Math, 'random').mockReturnValue(0)
      const config: RetryConfig = {
        maxRetries: 5,
        baseDelayMs: 1000,
        maxDelayMs: 5000,
        backoffMultiplier: 2,
      }

      // attempt 3: 1000 * 2^3 = 8000 -> capped at 5000
      expect(calculateBackoffDelay(3, config)).toBe(5000)

      vi.restoreAllMocks()
    })

    it('adds jitter to the delay', () => {
      vi.spyOn(Math, 'random').mockReturnValue(0.5) // 50% jitter
      const config: RetryConfig = {
        maxRetries: 3,
        baseDelayMs: 1000,
        maxDelayMs: 10000,
        backoffMultiplier: 2,
      }

      // attempt 0: base = 1000, jitter = 0.5 * 1000 * 0.5 = 250
      expect(calculateBackoffDelay(0, config)).toBe(1250)

      vi.restoreAllMocks()
    })

    it('uses default config when none provided', () => {
      vi.spyOn(Math, 'random').mockReturnValue(0)
      const delay = calculateBackoffDelay(0)
      expect(delay).toBe(1000) // default baseDelayMs
      vi.restoreAllMocks()
    })
  })

  // ─── isRetryableError ──────────────────────────────────────────

  describe('isRetryableError', () => {
    it('respects explicit retryable flag when true', () => {
      expect(isRetryableError({ success: false, retryable: true })).toBe(true)
    })

    it('respects explicit retryable flag when false', () => {
      expect(isRetryableError({ success: false, retryable: false })).toBe(false)
    })

    it('identifies gateway_timeout as retryable', () => {
      expect(isRetryableError({ success: false, error: 'gateway_timeout' })).toBe(true)
    })

    it('identifies network_error as retryable', () => {
      expect(isRetryableError({ success: false, error: 'network_error' })).toBe(true)
    })

    it('identifies rate_limited as retryable', () => {
      expect(isRetryableError({ success: false, error: 'rate_limited' })).toBe(true)
    })

    it('identifies service_unavailable as retryable', () => {
      expect(isRetryableError({ success: false, error: 'service_unavailable' })).toBe(true)
    })

    it('identifies internal_error as retryable', () => {
      expect(isRetryableError({ success: false, error: 'internal_error' })).toBe(true)
    })

    it('identifies card_declined as non-retryable', () => {
      expect(isRetryableError({ success: false, error: 'card_declined' })).toBe(false)
    })

    it('identifies insufficient_funds as non-retryable', () => {
      expect(isRetryableError({ success: false, error: 'insufficient_funds' })).toBe(false)
    })

    it('identifies invalid_card as non-retryable', () => {
      expect(isRetryableError({ success: false, error: 'invalid_card' })).toBe(false)
    })

    it('identifies expired_card as non-retryable', () => {
      expect(isRetryableError({ success: false, error: 'expired_card' })).toBe(false)
    })

    it('identifies fraud_detected as non-retryable', () => {
      expect(isRetryableError({ success: false, error: 'fraud_detected' })).toBe(false)
    })

    it('returns false for unknown errors not in either list', () => {
      expect(isRetryableError({ success: false, error: 'some_random_error' })).toBe(false)
    })

    it('returns false when no error is provided', () => {
      expect(isRetryableError({ success: false })).toBe(false)
    })
  })

  // ─── processPaymentWithRetry ───────────────────────────────────

  describe('processPaymentWithRetry', () => {
    const request: PaymentRequest = {
      orderId: 'ORD-001',
      amount: 99.99,
      currency: 'USD',
      cardToken: 'tok_test_123',
    }

    const fastConfig: RetryConfig = {
      maxRetries: 2,
      baseDelayMs: 10,
      maxDelayMs: 100,
      backoffMultiplier: 2,
    }

    it('succeeds on first attempt', async () => {
      const gateway = vi.fn<[PaymentRequest], Promise<PaymentResponse>>().mockResolvedValue({
        success: true,
        transactionId: 'txn_123',
      })

      const result = await processPaymentWithRetry(request, gateway, fastConfig)

      expect(result.success).toBe(true)
      expect(result.transactionId).toBe('txn_123')
      expect(result.attempts).toBe(1)
      expect(gateway).toHaveBeenCalledTimes(1)
    })

    it('retries on retryable errors and eventually succeeds', async () => {
      const gateway = vi.fn<[PaymentRequest], Promise<PaymentResponse>>()
        .mockResolvedValueOnce({ success: false, error: 'gateway_timeout' })
        .mockResolvedValueOnce({ success: true, transactionId: 'txn_456' })

      const promise = processPaymentWithRetry(request, gateway, fastConfig)

      // Advance timers for the backoff delays
      await vi.advanceTimersByTimeAsync(200)

      const result = await promise

      expect(result.success).toBe(true)
      expect(result.attempts).toBe(2)
      expect(gateway).toHaveBeenCalledTimes(2)
    })

    it('stops retrying on non-retryable error', async () => {
      const gateway = vi.fn<[PaymentRequest], Promise<PaymentResponse>>()
        .mockResolvedValue({ success: false, error: 'card_declined' })

      const result = await processPaymentWithRetry(request, gateway, fastConfig)

      expect(result.success).toBe(false)
      expect(result.error).toBe('card_declined')
      expect(result.attempts).toBe(1)
      expect(gateway).toHaveBeenCalledTimes(1)
    })

    it('exhausts all retries on persistent retryable errors', async () => {
      const gateway = vi.fn<[PaymentRequest], Promise<PaymentResponse>>()
        .mockResolvedValue({ success: false, error: 'gateway_timeout' })

      const promise = processPaymentWithRetry(request, gateway, fastConfig)
      await vi.advanceTimersByTimeAsync(1000)
      const result = await promise

      expect(result.success).toBe(false)
      expect(result.attempts).toBe(3) // 1 initial + 2 retries
      expect(gateway).toHaveBeenCalledTimes(3)
    })

    it('handles thrown exceptions as retryable', async () => {
      const gateway = vi.fn<[PaymentRequest], Promise<PaymentResponse>>()
        .mockRejectedValueOnce(new Error('network failure'))
        .mockResolvedValueOnce({ success: true, transactionId: 'txn_789' })

      const promise = processPaymentWithRetry(request, gateway, fastConfig)
      await vi.advanceTimersByTimeAsync(500)
      const result = await promise

      expect(result.success).toBe(true)
      expect(result.attempts).toBe(2)
    })

    it('handles all attempts throwing exceptions', async () => {
      const gateway = vi.fn<[PaymentRequest], Promise<PaymentResponse>>()
        .mockRejectedValue(new Error('persistent failure'))

      const promise = processPaymentWithRetry(request, gateway, fastConfig)
      await vi.advanceTimersByTimeAsync(1000)
      const result = await promise

      expect(result.success).toBe(false)
      expect(result.error).toBe('persistent failure')
      expect(result.attempts).toBe(3)
    })

    it('handles non-Error thrown values', async () => {
      const gateway = vi.fn<[PaymentRequest], Promise<PaymentResponse>>()
        .mockRejectedValueOnce('string error')
        .mockResolvedValueOnce({ success: true, transactionId: 'txn_000' })

      const promise = processPaymentWithRetry(request, gateway, fastConfig)
      await vi.advanceTimersByTimeAsync(500)
      const result = await promise

      expect(result.success).toBe(true)
    })
  })

  // ─── validatePaymentRequest ────────────────────────────────────

  describe('validatePaymentRequest', () => {
    const validRequest: PaymentRequest = {
      orderId: 'ORD-001',
      amount: 99.99,
      currency: 'USD',
      cardToken: 'tok_test_123',
    }

    it('returns null for a valid request', () => {
      expect(validatePaymentRequest(validRequest)).toBeNull()
    })

    it('rejects empty orderId', () => {
      expect(validatePaymentRequest({ ...validRequest, orderId: '' })).toBe(
        'Order ID is required'
      )
    })

    it('rejects whitespace-only orderId', () => {
      expect(validatePaymentRequest({ ...validRequest, orderId: '   ' })).toBe(
        'Order ID is required'
      )
    })

    it('rejects zero amount', () => {
      expect(validatePaymentRequest({ ...validRequest, amount: 0 })).toBe(
        'Payment amount must be positive'
      )
    })

    it('rejects negative amount', () => {
      expect(validatePaymentRequest({ ...validRequest, amount: -10 })).toBe(
        'Payment amount must be positive'
      )
    })

    it('rejects empty currency', () => {
      expect(validatePaymentRequest({ ...validRequest, currency: '' })).toBe(
        'Valid 3-letter currency code is required'
      )
    })

    it('rejects 2-letter currency code', () => {
      expect(validatePaymentRequest({ ...validRequest, currency: 'US' })).toBe(
        'Valid 3-letter currency code is required'
      )
    })

    it('rejects 4-letter currency code', () => {
      expect(validatePaymentRequest({ ...validRequest, currency: 'USDD' })).toBe(
        'Valid 3-letter currency code is required'
      )
    })

    it('rejects empty cardToken', () => {
      expect(validatePaymentRequest({ ...validRequest, cardToken: '' })).toBe(
        'Card token is required'
      )
    })

    it('rejects whitespace-only cardToken', () => {
      expect(validatePaymentRequest({ ...validRequest, cardToken: '   ' })).toBe(
        'Card token is required'
      )
    })
  })
})

import { expect, afterEach, vi } from 'vitest'
import { cleanup } from '@testing-library/react'
import '@testing-library/jest-dom'

afterEach(() => {
  cleanup()
})

// Mock environment variables
process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY = 'pk_test_mock'
process.env.STRIPE_SECRET_KEY = 'sk_test_mock'

import { NextRequest, NextResponse } from 'next/server'
import Stripe from 'stripe'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || '', {
  apiVersion: '2023-10-16',
})

// QUALITY GAP: Missing input validation on amount — accepts any number including
// negative values, zero, or absurdly large amounts. No type checking on body fields.
// No rate limiting. No CSRF protection.
export async function POST(request: NextRequest) {
  try {
    const body = await request.json()

    const { amount, currency, email } = body

    const paymentIntent = await stripe.paymentIntents.create({
      amount: Math.round(amount),
      currency: currency || 'usd',
      metadata: {
        customer_email: email,
      },
    })

    return NextResponse.json({
      clientSecret: paymentIntent.client_secret,
    })
  } catch (error) {
    console.error('Payment intent error:', error)
    return NextResponse.json(
      { error: 'Failed to create payment intent' },
      { status: 500 }
    )
  }
}

import { describe, it, expect } from 'vitest'
import {
  validateEmail,
  validateZipCode,
  validateName,
  validateAddress,
  validateGdprConsent,
  validateCheckoutForm,
  validatePaymentAmount,
  type FormData,
} from '@/src/lib/validation'

describe('Form Validation', () => {
  describe('Email validation', () => {
    it('should accept valid emails', () => {
      expect(validateEmail('user@example.com')).toBeNull()
      expect(validateEmail('test.email@domain.co.uk')).toBeNull()
      expect(validateEmail('user+tag@example.com')).toBeNull()
    })

    it('should reject invalid emails', () => {
      expect(validateEmail('invalid')).not.toBeNull()
      expect(validateEmail('user@')).not.toBeNull()
      expect(validateEmail('@example.com')).not.toBeNull()
      expect(validateEmail('user @example.com')).not.toBeNull()
      expect(validateEmail('')).not.toBeNull()
    })
  })

  describe('Zip code validation', () => {
    it('should accept valid US zip codes', () => {
      expect(validateZipCode('12345')).toBeNull()
      expect(validateZipCode('12345-6789')).toBeNull()
    })

    it('should reject invalid zip codes', () => {
      expect(validateZipCode('1234')).not.toBeNull()
      expect(validateZipCode('123456')).not.toBeNull()
      expect(validateZipCode('abcde')).not.toBeNull()
      expect(validateZipCode('')).not.toBeNull()
    })
  })

  describe('Name validation', () => {
    it('should accept valid names', () => {
      expect(validateName('John Doe')).toBeNull()
      expect(validateName('AB')).toBeNull()
      expect(validateName('Mary Jane Watson')).toBeNull()
    })

    it('should reject invalid names', () => {
      expect(validateName('')).not.toBeNull()
      expect(validateName('   ')).not.toBeNull()
      expect(validateName('A')).not.toBeNull()
    })
  })

  describe('Address validation', () => {
    it('should accept valid addresses', () => {
      expect(validateAddress('123 Main Street')).toBeNull()
      expect(validateAddress('1600 Pennsylvania Avenue')).toBeNull()
    })

    it('should reject invalid addresses', () => {
      expect(validateAddress('')).not.toBeNull()
      expect(validateAddress('   ')).not.toBeNull()
      expect(validateAddress('123')).not.toBeNull()
      expect(validateAddress('St')).not.toBeNull()
    })
  })

  describe('GDPR consent validation', () => {
    it('should accept consent when true', () => {
      expect(validateGdprConsent(true)).toBeNull()
    })

    it('should reject consent when false', () => {
      expect(validateGdprConsent(false)).not.toBeNull()
    })
  })

  describe('Payment amount validation', () => {
    it('should accept positive amounts', () => {
      expect(validatePaymentAmount(100)).toBeNull()
      expect(validatePaymentAmount(0.01)).toBeNull()
    })

    it('should reject zero or negative amounts', () => {
      expect(validatePaymentAmount(0)).not.toBeNull()
      expect(validatePaymentAmount(-10)).not.toBeNull()
    })
  })

  describe('Full checkout form validation', () => {
    it('should validate a complete valid form', () => {
      const validForm: FormData = {
        name: 'John Doe',
        email: 'john@example.com',
        address: '123 Main Street',
        zipCode: '12345',
        gdprConsent: true,
      }
      const errors = validateCheckoutForm(validForm)
