// Advanced email validation beyond basic regex
// Provides detailed validation for email addresses with specific rules

export interface EmailValidationResult {
  valid: boolean
  error?: string
  normalized?: string
  domain?: string
  localPart?: string
}

/**
 * List of known disposable email domains
 */
const DISPOSABLE_DOMAINS = [
  'mailinator.com',
  'guerrillamail.com',
  'tempmail.com',
  'throwaway.email',
  'yopmail.com',
  'trashmail.com',
  '10minutemail.com',
  'fakeinbox.com',
]

/**
 * Validates an email address with detailed results
 */
export const validateEmailDetailed = (email: string): EmailValidationResult => {
  if (!email || email.trim().length === 0) {
    return { valid: false, error: 'Email is required' }
  }

  const trimmed = email.trim().toLowerCase()

  // Check basic format
  const atIndex = trimmed.lastIndexOf('@')
  if (atIndex < 1) {
    return { valid: false, error: 'Email must contain @ symbol' }
  }

  const localPart = trimmed.substring(0, atIndex)
  const domain = trimmed.substring(atIndex + 1)

  // Validate local part
  if (localPart.length === 0) {
    return { valid: false, error: 'Email local part is empty' }
  }

  if (localPart.length > 64) {
    return { valid: false, error: 'Email local part exceeds 64 characters' }
  }

  // Check for consecutive dots in local part
  if (/\.\./.test(localPart)) {
    return { valid: false, error: 'Email cannot contain consecutive dots' }
  }

  // Check if local part starts or ends with a dot
  if (localPart.startsWith('.') || localPart.endsWith('.')) {
    return { valid: false, error: 'Email cannot start or end with a dot' }
  }

  // Validate domain
  if (domain.length === 0) {
    return { valid: false, error: 'Email domain is empty' }
  }

  if (!domain.includes('.')) {
    return { valid: false, error: 'Email domain must contain a dot' }
  }

  // Check domain parts
  const domainParts = domain.split('.')
  for (const part of domainParts) {
    if (part.length === 0) {
      return { valid: false, error: 'Email domain has empty labels' }
    }
    if (part.length > 63) {
      return { valid: false, error: 'Email domain label exceeds 63 characters' }
    }
    if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/.test(part)) {
      return { valid: false, error: 'Email domain contains invalid characters' }
    }
  }

  // Check TLD length
  const tld = domainParts[domainParts.length - 1]
  if (tld.length < 2) {
    return { valid: false, error: 'Email TLD must be at least 2 characters' }
  }

  // Total email length check (RFC 5321)
  if (trimmed.length > 254) {
    return { valid: false, error: 'Email exceeds maximum length of 254 characters' }
  }

  return {
    valid: true,
    normalized: trimmed,
    domain,
    localPart,
  }
}

/**
 * Checks if an email uses a disposable/temporary email domain
 */
export const isDisposableEmail = (email: string): boolean => {
  const result = validateEmailDetailed(email)
  if (!result.valid || !result.domain) return false
  return DISPOSABLE_DOMAINS.includes(result.domain)
}

/**
 * Normalizes an email address (lowercase, trim, handle Gmail dots/plus)
 */
export const normalizeEmail = (email: string): string | null => {
  const result = validateEmailDetailed(email)
  if (!result.valid || !result.normalized) return null

  let { localPart, domain } = result

  // Gmail-specific normalization: remove dots and +suffix from local part
  if (domain === 'gmail.com' || domain === 'googlemail.com') {
    localPart = localPart!.split('+')[0].replace(/\./g, '')
    domain = 'gmail.com' // Normalize googlemail.com to gmail.com
  }

  return `${localPart}@${domain}`
}

/**
 * Suggests corrections for common email typos
 */
export const suggestEmailCorrection = (email: string): string | null => {
  const result = validateEmailDetailed(email)
  if (!result.domain) return null

  const corrections: Record<string, string> = {
    'gmial.com': 'gmail.com',
    'gmal.com': 'gmail.com',
    'gamil.com': 'gmail.com',
    'gnail.com': 'gmail.com',
    'gmail.co': 'gmail.com',
    'hotmal.com': 'hotmail.com',
    'hotmial.com': 'hotmail.com',
    'hotmail.co': 'hotmail.com',
    'yahooo.com': 'yahoo.com',
    'yaho.com': 'yahoo.com',
    'outloo.com': 'outlook.com',
    'outlok.com': 'outlook.com',
  }

  const correctedDomain = corrections[result.domain]
  if (correctedDomain) {
    return `${result.localPart}@${correctedDomain}`
  }

  return null
}

// Payment gateway retry logic with exponential backoff
// Handles transient failures when processing payments

export interface PaymentRequest {
  orderId: string
  amount: number
  currency: string
  cardToken: string
}

export interface PaymentResponse {
  success: boolean
  transactionId?: string
  error?: string
  retryable?: boolean
}

export interface RetryConfig {
  maxRetries: number
  baseDelayMs: number
  maxDelayMs: number
  backoffMultiplier: number
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxRetries: 3,
  baseDelayMs: 1000,
  maxDelayMs: 10000,
  backoffMultiplier: 2,
}

/**
 * Calculates the delay for a given retry attempt using exponential backoff with jitter
 */
export const calculateBackoffDelay = (
  attempt: number,
  config: RetryConfig = DEFAULT_RETRY_CONFIG
): number => {
  const exponentialDelay = config.baseDelayMs * Math.pow(config.backoffMultiplier, attempt)
  const cappedDelay = Math.min(exponentialDelay, config.maxDelayMs)
  // Add jitter: random value between 0 and 50% of the delay
  const jitter = Math.random() * cappedDelay * 0.5
  return Math.floor(cappedDelay + jitter)
}

/**
 * Determines if a payment error is retryable
 */
export const isRetryableError = (response: PaymentResponse): boolean => {
  if (response.retryable !== undefined) return response.retryable

  // Known non-retryable errors
  const nonRetryable = [
    'card_declined',
    'insufficient_funds',
    'invalid_card',
    'expired_card',
    'fraud_detected',
  ]

  if (response.error && nonRetryable.includes(response.error)) {
    return false
  }

  // Network/server errors are retryable
  const retryable = [
    'gateway_timeout',
    'network_error',
    'rate_limited',
    'service_unavailable',
    'internal_error',
  ]

  return response.error ? retryable.includes(response.error) : false
}

/**
 * Processes a payment with retry logic
 * @param request - The payment request
 * @param gateway - The payment processing function
 * @param config - Retry configuration
 * @returns The final payment response
 */
export const processPaymentWithRetry = async (
  request: PaymentRequest,
  gateway: (req: PaymentRequest) => Promise<PaymentResponse>,
  config: RetryConfig = DEFAULT_RETRY_CONFIG
): Promise<PaymentResponse & { attempts: number }> => {
  let lastResponse: PaymentResponse | null = null

  for (let attempt = 0; attempt <= config.maxRetries; attempt++) {
    try {
      const response = await gateway(request)
      lastResponse = response

      if (response.success) {
        return { ...response, attempts: attempt + 1 }
      }

      if (!isRetryableError(response)) {
        return { ...response, attempts: attempt + 1 }
      }

      // Don't delay after the last attempt
      if (attempt < config.maxRetries) {
        const delay = calculateBackoffDelay(attempt, config)
        await new Promise(resolve => setTimeout(resolve, delay))
      }
    } catch (error) {
      lastResponse = {
        success: false,
        error: error instanceof Error ? error.message : 'unknown_error',
        retryable: true,
      }

      if (attempt < config.maxRetries) {
        const delay = calculateBackoffDelay(attempt, config)
        await new Promise(resolve => setTimeout(resolve, delay))
      }
    }
  }

  return {
    ...(lastResponse || { success: false, error: 'max_retries_exceeded' }),
    attempts: config.maxRetries + 1,
  }
}

/**
 * Validates a payment request before processing
 */
export const validatePaymentRequest = (request: PaymentRequest): string | null => {
  if (!request.orderId || request.orderId.trim().length === 0) {
    return 'Order ID is required'
  }
  if (!request.amount || request.amount <= 0) {
    return 'Payment amount must be positive'
  }
  if (!request.currency || request.currency.length !== 3) {
    return 'Valid 3-letter currency code is required'
  }
  if (!request.cardToken || request.cardToken.trim().length === 0) {
    return 'Card token is required'
  }
  return null
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import {
  createTokenBucket,
  createSlidingWindow,
  createRateLimiter,
  formatRateLimitHeaders,
  validateRateLimitConfig,
  type RateLimitConfig,
  type RateLimitResult,
} from '@/src/lib/rate-limiter'

describe('rate-limiter.ts — rate limiting', () => {
  beforeEach(() => {
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2025-01-01T00:00:00Z'))
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  // ─── Token Bucket ──────────────────────────────────────────────

  describe('createTokenBucket', () => {
    const config: RateLimitConfig = {
      maxRequests: 5,
      windowMs: 10000,
      strategy: 'token-bucket',
    }

    it('allows requests up to maxRequests', () => {
      const limiter = createTokenBucket(config)
      for (let i = 0; i < 5; i++) {
        const result = limiter.consume()
        expect(result.allowed).toBe(true)
      }
    })

    it('blocks requests after tokens are exhausted', () => {
      const limiter = createTokenBucket(config)
      for (let i = 0; i < 5; i++) {
        limiter.consume()
      }
      const result = limiter.consume()
      expect(result.allowed).toBe(false)
      expect(result.remaining).toBe(0)
    })

    it('returns remaining count accurately', () => {
      const limiter = createTokenBucket(config)
      limiter.consume()
      limiter.consume()
      const result = limiter.consume()
      expect(result.allowed).toBe(true)
      expect(result.remaining).toBe(2)
    })

    it('refills tokens over time', () => {
      const limiter = createTokenBucket(config)

      // Exhaust all tokens
      for (let i = 0; i < 5; i++) {
        limiter.consume()
      }

      // Advance time to allow some refill
      // Rate: 5 tokens / 10000ms = 0.5 tokens/ms -> 1 token = 2000ms
      vi.advanceTimersByTime(2000)

      const result = limiter.consume()
      expect(result.allowed).toBe(true)
    })

    it('does not exceed maxRequests after long idle', () => {
      const limiter = createTokenBucket(config)

      // Exhaust tokens
      for (let i = 0; i < 5; i++) {
        limiter.consume()
      }

      // Wait a very long time
      vi.advanceTimersByTime(100000)

      const state = limiter.getState()
      // After refill, tokens should be capped at maxRequests
      // Need to trigger refill via consume
      limiter.consume()
      const stateAfter = limiter.getState()
      expect(stateAfter.tokens).toBeLessThanOrEqual(config.maxRequests)
    })

    it('provides retryAfterMs when blocked', () => {
      const limiter = createTokenBucket(config)

      for (let i = 0; i < 5; i++) {
        limiter.consume()
      }

      const result = limiter.consume()
      expect(result.allowed).toBe(false)
      expect(result.retryAfterMs).toBeDefined()
      expect(result.retryAfterMs!).toBeGreaterThan(0)
    })

    it('reset restores all tokens', () => {
      const limiter = createTokenBucket(config)

      for (let i = 0; i < 5; i++) {
        limiter.consume()
      }

      limiter.reset()
      const result = limiter.consume()
      expect(result.allowed).toBe(true)
      expect(result.remaining).toBe(4)
    })

    it('getState returns current token count', () => {
      const limiter = createTokenBucket(config)
      const state = limiter.getState()
      expect(state.tokens).toBe(5)
      expect(state.lastRefill).toBeDefined()
    })
  })

  // ─── Sliding Window ────────────────────────────────────────────

  describe('createSlidingWindow', () => {
    const config: RateLimitConfig = {
      maxRequests: 3,
      windowMs: 5000,
      strategy: 'sliding-window',
    }

    it('allows requests up to maxRequests', () => {
      const limiter = createSlidingWindow(config)
      for (let i = 0; i < 3; i++) {
        const result = limiter.consume()
        expect(result.allowed).toBe(true)
      }
    })

    it('blocks requests after maxRequests in window', () => {
      const limiter = createSlidingWindow(config)
      for (let i = 0; i < 3; i++) {
        limiter.consume()
      }
      const result = limiter.consume()
      expect(result.allowed).toBe(false)
      expect(result.remaining).toBe(0)
    })

    it('returns correct remaining count', () => {
      const limiter = createSlidingWindow(config)
      limiter.consume()
      const result = limiter.consume()
      expect(result.remaining).toBe(1)
    })

    it('allows requests after oldest request leaves window', () => {
      const limiter = createSlidingWindow(config)

      // Make 3 requests at time 0
      for (let i = 0; i < 3; i++) {
        limiter.consume()
      }

      // 4th request blocked
      expect(limiter.consume().allowed).toBe(false)

      // Advance past window
      vi.advanceTimersByTime(5001)

      // Now allowed again
      const result = limiter.consume()
      expect(result.allowed).toBe(true)
    })

    it('sliding behavior: staggered requests slide out individually', () => {
      const limiter = createSlidingWindow(config)

      // Request at t=0
      limiter.consume()

      // Request at t=2000
      vi.advanceTimersByTime(2000)
      limiter.consume()

      // Request at t=4000
      vi.advanceTimersByTime(2000)
      limiter.consume()

      // Blocked at t=4000 (3 requests within 5s window)
      expect(limiter.consume().allowed).toBe(false)

      // At t=5001, first request (t=0) slides out
      vi.advanceTimersByTime(1001)
      expect(limiter.consume().allowed).toBe(true)
    })

    it('provides retryAfterMs when blocked', () => {
      const limiter = createSlidingWindow(config)
      for (let i = 0; i < 3; i++) {
        limiter.consume()
      }
      const result = limiter.consume()
      expect(result.retryAfterMs).toBeDefined()
      expect(result.retryAfterMs!).toBeGreaterThanOrEqual(0)
    })

    it('reset clears all timestamps', () => {
      const limiter = createSlidingWindow(config)
      for (let i = 0; i < 3; i++) {
        limiter.consume()
      }
      limiter.reset()
      const result = limiter.consume()
      expect(result.allowed).toBe(true)
      expect(result.remaining).toBe(2)
    })

    it('getState returns current count', () => {
      const limiter = createSlidingWindow(config)
      limiter.consume()
      limiter.consume()
      const state = limiter.getState()
      expect(state.count).toBe(2)
    })
  })

  // ─── createRateLimiter factory ─────────────────────────────────

  describe('createRateLimiter', () => {
    it('creates a token bucket when strategy is token-bucket', () => {
      const limiter = createRateLimiter({
        maxRequests: 10,
        windowMs: 60000,
        strategy: 'token-bucket',
      })
      // Token bucket has getState with .tokens
      const state = limiter.getState()
      expect('tokens' in state).toBe(true)
    })

    it('creates a sliding window when strategy is sliding-window', () => {
      const limiter = createRateLimiter({
        maxRequests: 10,
        windowMs: 60000,
        strategy: 'sliding-window',
      })
      const state = limiter.getState()
      expect('count' in state).toBe(true)
    })
  })

  // ─── formatRateLimitHeaders ────────────────────────────────────

  describe('formatRateLimitHeaders', () => {
    it('includes remaining and reset headers for allowed requests', () => {
      const result: RateLimitResult = {
        allowed: true,
        remaining: 5,
        resetAt: Date.now() + 10000,
      }

      const headers = formatRateLimitHeaders(result)
      expect(headers['X-RateLimit-Remaining']).toBe('5')
      expect(headers['X-RateLimit-Reset']).toBeDefined()
      expect(headers['Retry-After']).toBeUndefined()
    })

    it('includes Retry-After header when blocked', () => {
      const result: RateLimitResult = {
        allowed: false,
        remaining: 0,
        resetAt: Date.now() + 10000,
        retryAfterMs: 5000,
      }

      const headers = formatRateLimitHeaders(result)
      expect(headers['Retry-After']).toBe('5')
    })

    it('does not include Retry-After when allowed', () => {
      const result: RateLimitResult = {
        allowed: true,
        remaining: 3,
        resetAt: Date.now() + 10000,
      }

      const headers = formatRateLimitHeaders(result)
      expect(headers).not.toHaveProperty('Retry-After')
    })

    it('rounds Retry-After up to nearest second', () => {
      const result: RateLimitResult = {
        allowed: false,
        remaining: 0,
        resetAt: Date.now() + 10000,
        retryAfterMs: 1500,
      }

      const headers = formatRateLimitHeaders(result)
      expect(headers['Retry-After']).toBe('2')
    })

    it('formats resetAt as UTC date string', () => {
      const resetTime = new Date('2025-01-01T00:00:10Z').getTime()
      const result: RateLimitResult = {
        allowed: true,
        remaining: 1,
        resetAt: resetTime,
      }

      const headers = formatRateLimitHeaders(result)
      expect(headers['X-RateLimit-Reset']).toBe(new Date(resetTime).toUTCString())
    })
  })

  // ─── validateRateLimitConfig ───────────────────────────────────

  describe('validateRateLimitConfig', () => {
    it('returns null for valid config', () => {
      expect(
        validateRateLimitConfig({
          maxRequests: 100,
          windowMs: 60000,
          strategy: 'token-bucket',
        })
      ).toBeNull()
    })

    it('returns null for sliding-window strategy', () => {
      expect(
        validateRateLimitConfig({
          maxRequests: 10,
          windowMs: 1000,
          strategy: 'sliding-window',
        })
      ).toBeNull()
    })

    it('rejects zero maxRequests', () => {
      expect(
        validateRateLimitConfig({
          maxRequests: 0,
          windowMs: 60000,
          strategy: 'token-bucket',
        })
      ).toBe('maxRequests must be a positive number')
    })

    it('rejects negative maxRequests', () => {
      expect(
        validateRateLimitConfig({
          maxRequests: -5,
          windowMs: 60000,
          strategy: 'token-bucket',
        })
      ).toBe('maxRequests must be a positive number')
    })

    it('rejects zero windowMs', () => {
      expect(
        validateRateLimitConfig({
          maxRequests: 10,
          windowMs: 0,
          strategy: 'token-bucket',
        })
      ).toBe('windowMs must be a positive number')
    })

    it('rejects negative windowMs', () => {
      expect(
        validateRateLimitConfig({
          maxRequests: 10,
          windowMs: -1000,
          strategy: 'token-bucket',
        })
      ).toBe('windowMs must be a positive number')
    })

    it('rejects invalid strategy', () => {
      expect(
        validateRateLimitConfig({
          maxRequests: 10,
          windowMs: 60000,
          strategy: 'fixed-window' as RateLimitConfig['strategy'],
        })
      ).toBe('strategy must be "token-bucket" or "sliding-window"')
    })
  })
})

