      value: { orderId: 'ORD-001', total: 99.99 },
    }

    it('returns null for a valid event', () => {
      expect(validateEvent(validEvent)).toBeNull()
    })

    it('rejects empty topic', () => {
      expect(validateEvent({ ...validEvent, topic: '' })).toBe('Topic is required')
    })

    it('rejects whitespace-only topic', () => {
      expect(validateEvent({ ...validEvent, topic: '   ' })).toBe('Topic is required')
    })

    it('rejects topic starting with non-alphanumeric', () => {
      expect(validateEvent({ ...validEvent, topic: '-orders' })).toBe(
        'Topic name must start with alphanumeric and contain only lowercase letters, numbers, dots, dashes, or underscores'
      )
    })

    it('rejects topic with uppercase letters', () => {
      expect(validateEvent({ ...validEvent, topic: 'Orders.Created' })).toBe(
        'Topic name must start with alphanumeric and contain only lowercase letters, numbers, dots, dashes, or underscores'
      )
    })

    it('rejects topic with spaces', () => {
      expect(validateEvent({ ...validEvent, topic: 'orders created' })).toBe(
        'Topic name must start with alphanumeric and contain only lowercase letters, numbers, dots, dashes, or underscores'
      )
    })

    it('accepts topic with dots, dashes, and underscores', () => {
      expect(validateEvent({ ...validEvent, topic: 'orders.created-v2_test' })).toBeNull()
    })

    it('rejects topic exceeding 249 characters', () => {
      const longTopic = 'a'.repeat(250)
      expect(validateEvent({ ...validEvent, topic: longTopic })).toBe(
        'Topic name exceeds maximum length of 249 characters'
      )
    })

    it('accepts topic of exactly 249 characters', () => {
      const topic = 'a'.repeat(249)
      expect(validateEvent({ ...validEvent, topic })).toBeNull()
    })

    it('rejects empty key', () => {
      expect(validateEvent({ ...validEvent, key: '' })).toBe('Event key is required')
    })

    it('rejects whitespace-only key', () => {
      expect(validateEvent({ ...validEvent, key: '   ' })).toBe('Event key is required')
    })

    it('rejects null value', () => {
      expect(
        validateEvent({ ...validEvent, value: null as unknown as Record<string, unknown> })
      ).toBe('Event value must be a non-null object')
    })

    it('rejects non-object value', () => {
      expect(
        validateEvent({ ...validEvent, value: 'string' as unknown as Record<string, unknown> })
      ).toBe('Event value must be a non-null object')
    })
  })

  // ─── serializeEvent ────────────────────────────────────────────

  describe('serializeEvent', () => {
    it('serializes event to JSON string', () => {
      const event: KafkaEvent = {
        topic: 'orders.created',
        key: 'ORD-001',
        value: { total: 99.99 },
        headers: { 'content-type': 'application/json' },
        timestamp: 1000000,
      }

      const serialized = serializeEvent(event)
      const parsed = JSON.parse(serialized)

      expect(parsed.key).toBe('ORD-001')
      expect(parsed.value).toEqual({ total: 99.99 })
      expect(parsed.headers).toEqual({ 'content-type': 'application/json' })
      expect(parsed.timestamp).toBe(1000000)
    })

    it('uses empty headers when none provided', () => {
      const event: KafkaEvent = {
        topic: 'test',
        key: 'k1',
        value: { data: true },
      }

      const parsed = JSON.parse(serializeEvent(event))
      expect(parsed.headers).toEqual({})
    })

    it('uses current timestamp when none provided', () => {
      vi.useFakeTimers()
      vi.setSystemTime(new Date('2025-01-01T00:00:00Z'))

      const event: KafkaEvent = {
        topic: 'test',
        key: 'k1',
        value: { data: true },
      }

      const parsed = JSON.parse(serializeEvent(event))
      expect(parsed.timestamp).toBe(Date.now())

      vi.useRealTimers()
    })
  })

  // ─── deserializeEvent ──────────────────────────────────────────

  describe('deserializeEvent', () => {
    it('deserializes valid JSON', () => {
      const data = JSON.stringify({
        topic: 'orders.created',
        key: 'ORD-001',
        value: { total: 99.99 },
        headers: {},
        timestamp: 1000,
      })

      const event = deserializeEvent(data)
      expect(event).not.toBeNull()
      expect(event!.key).toBe('ORD-001')
      expect(event!.value).toEqual({ total: 99.99 })
    })

    it('returns null for invalid JSON', () => {
      expect(deserializeEvent('not json{')).toBeNull()
    })

    it('returns null when key is missing', () => {
      expect(deserializeEvent(JSON.stringify({ value: {} }))).toBeNull()
    })

    it('returns null when value is missing', () => {
      expect(deserializeEvent(JSON.stringify({ key: 'k1' }))).toBeNull()
    })

    it('uses empty string for topic when missing', () => {
      const data = JSON.stringify({ key: 'k1', value: { x: 1 } })
      const event = deserializeEvent(data)
      expect(event!.topic).toBe('')
    })
  })

  // ─── createOrderEvent ──────────────────────────────────────────

  describe('createOrderEvent', () => {
    it('creates an event with correct topic', () => {
      const event = createOrderEvent('created', 'ORD-001', { total: 99.99 })
      expect(event.topic).toBe('orders.created')
    })

    it('uses orderId as event key', () => {
      const event = createOrderEvent('shipped', 'ORD-002', {})
      expect(event.key).toBe('ORD-002')
    })

    it('includes event metadata in value', () => {
      const event = createOrderEvent('cancelled', 'ORD-003', { reason: 'customer request' })
      expect(event.value.eventType).toBe('cancelled')
      expect(event.value.orderId).toBe('ORD-003')
      expect(event.value.data).toEqual({ reason: 'customer request' })
      expect(event.value.version).toBe(1)
      expect(event.value.producedAt).toBeDefined()
    })

    it('sets appropriate headers', () => {
      const event = createOrderEvent('refunded', 'ORD-004', {})
      expect(event.headers!['event-type']).toBe('refunded')
      expect(event.headers!['content-type']).toBe('application/json')
      expect(event.headers!['correlation-id']).toContain('corr-ORD-004-')
    })
  })

  // ─── batchEvents ───────────────────────────────────────────────

  describe('batchEvents', () => {
    const makeEvents = (n: number): KafkaEvent[] =>
      Array.from({ length: n }, (_, i) => ({
        topic: 'test',
        key: `k${i}`,
        value: { i },
      }))

    it('returns a single batch when events fit', () => {
      const events = makeEvents(5)
      const batches = batchEvents(events, 10)
      expect(batches).toHaveLength(1)
      expect(batches[0]).toHaveLength(5)
    })

    it('splits events into correct batch sizes', () => {
      const events = makeEvents(10)
      const batches = batchEvents(events, 3)
      expect(batches).toHaveLength(4) // 3, 3, 3, 1
      expect(batches[0]).toHaveLength(3)
      expect(batches[3]).toHaveLength(1)
    })

    it('handles empty array', () => {
      const batches = batchEvents([], 10)
      expect(batches).toHaveLength(0)
    })

    it('handles batch size of 1', () => {
      const events = makeEvents(3)
      const batches = batchEvents(events, 1)
      expect(batches).toHaveLength(3)
      expect(batches[0]).toHaveLength(1)
    })

    it('uses default batch size from config', () => {
      const events = makeEvents(150)
      const batches = batchEvents(events) // default = 100
      expect(batches).toHaveLength(2)
      expect(batches[0]).toHaveLength(100)
      expect(batches[1]).toHaveLength(50)
    })
  })

  // ─── publishEvent ──────────────────────────────────────────────

  describe('publishEvent', () => {
    const validEvent: KafkaEvent = {
      topic: 'orders.created',
      key: 'ORD-001',
      value: { total: 99.99 },
    }

    it('publishes successfully', async () => {
      const sendFn = vi.fn().mockResolvedValue({
        success: true,
        partition: 0,
        offset: '42',
        timestamp: Date.now(),
      })

      const result = await publishEvent(validEvent, sendFn)
      expect(result.success).toBe(true)
      expect(result.partition).toBe(0)
      expect(sendFn).toHaveBeenCalledTimes(1)
    })

    it('returns validation error without calling sendFn', async () => {
      const sendFn = vi.fn()
      const result = await publishEvent({ ...validEvent, topic: '' }, sendFn)
      expect(result.success).toBe(false)
      expect(result.error).toBe('Topic is required')
      expect(sendFn).not.toHaveBeenCalled()
    })

    it('handles sendFn throwing an Error', async () => {
      const sendFn = vi.fn().mockRejectedValue(new Error('Connection refused'))
      const result = await publishEvent(validEvent, sendFn)
      expect(result.success).toBe(false)
      expect(result.error).toBe('Connection refused')
    })

    it('handles sendFn throwing a non-Error', async () => {
      const sendFn = vi.fn().mockRejectedValue('string error')
      const result = await publishEvent(validEvent, sendFn)
      expect(result.success).toBe(false)
      expect(result.error).toBe('Unknown publish error')
    })
  })

  // ─── publishBatch ──────────────────────────────────────────────

  describe('publishBatch', () => {
    const makeEvents = (n: number): KafkaEvent[] =>
      Array.from({ length: n }, (_, i) => ({
        topic: 'orders.created',
        key: `ORD-${i}`,
        value: { index: i },
      }))

    it('publishes all events and returns results', async () => {
      const sendFn = vi.fn().mockResolvedValue({
        success: true,
        partition: 0,
        offset: '1',
        timestamp: Date.now(),
      })

      const results = await publishBatch(makeEvents(3), sendFn, { batchSize: 10 })
      expect(results).toHaveLength(3)
      expect(results.every(r => r.success)).toBe(true)
    })

    it('handles mixed success and failure', async () => {
      let callCount = 0
      const sendFn = vi.fn().mockImplementation(() => {
        callCount++
        if (callCount === 2) return Promise.reject(new Error('fail'))
        return Promise.resolve({
          success: true,
          partition: 0,
          offset: String(callCount),
          timestamp: Date.now(),
        })
      })

      const results = await publishBatch(makeEvents(3), sendFn, { batchSize: 10 })
      expect(results).toHaveLength(3)

      const successes = results.filter(r => r.success)
      const failures = results.filter(r => !r.success)
      expect(successes).toHaveLength(2)
      expect(failures).toHaveLength(1)
    })

    it('processes events in batches', async () => {
      const callOrder: number[] = []
      const sendFn = vi.fn().mockImplementation((_s: string, _t: string) => {
        callOrder.push(callOrder.length)
        return Promise.resolve({ success: true, timestamp: Date.now() })
      })

      await publishBatch(makeEvents(5), sendFn, { batchSize: 2 })
      expect(sendFn).toHaveBeenCalledTimes(5)
    })

    it('handles empty event array', async () => {
      const sendFn = vi.fn()
      const results = await publishBatch([], sendFn)
      expect(results).toHaveLength(0)
      expect(sendFn).not.toHaveBeenCalled()
    })
  })
})

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import {
  generateSessionId,
  createGuestSession,
  getGuestSession,
  saveGuestSession,
  addToGuestCart,
  removeFromGuestCart,
  updateGuestCartQuantity,
  getGuestCartTotal,
  clearGuestSession,
  setCheckoutStep,
  isSessionValid,
  type GuestSession,
} from '@/src/lib/guest-session'

// Mock localStorage
const localStorageMock = (() => {
  let store: Record<string, string> = {}
  return {
    getItem: vi.fn((key: string) => store[key] ?? null),
    setItem: vi.fn((key: string, value: string) => { store[key] = value }),
    removeItem: vi.fn((key: string) => { delete store[key] }),
    clear: vi.fn(() => { store = {} }),
    get length() { return Object.keys(store).length },
    key: vi.fn((index: number) => Object.keys(store)[index] ?? null),
  }
})()

Object.defineProperty(globalThis, 'localStorage', { value: localStorageMock })

describe('guest-session.ts — guest session management', () => {
  beforeEach(() => {
    localStorageMock.clear()
    vi.clearAllMocks()
    vi.useFakeTimers()
    vi.setSystemTime(new Date('2025-06-15T12:00:00Z'))
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  // ─── generateSessionId ────────────────────────────────────────

  describe('generateSessionId', () => {
    it('returns a string starting with gs_', () => {
      const id = generateSessionId()
      expect(id).toMatch(/^gs_/)
    })

    it('generates unique IDs', () => {
      const ids = new Set(Array.from({ length: 100 }, () => generateSessionId()))
      expect(ids.size).toBe(100)
    })

    it('has a reasonable length', () => {
      const id = generateSessionId()
      expect(id.length).toBeGreaterThan(10)
      expect(id.length).toBeLessThan(50)
    })
  })

  // ─── createGuestSession ───────────────────────────────────────

  describe('createGuestSession', () => {
    it('creates a session with correct structure', () => {
      const session = createGuestSession()
      expect(session).toHaveProperty('id')
      expect(session).toHaveProperty('createdAt')
      expect(session).toHaveProperty('expiresAt')
      expect(session).toHaveProperty('cartItems')
      expect(session).toHaveProperty('checkoutStep')
    })

    it('initializes with empty cart and step 0', () => {
      const session = createGuestSession()
      expect(session.cartItems).toEqual([])
      expect(session.checkoutStep).toBe(0)
    })

    it('sets expiresAt to 24 hours from now', () => {
      const now = Date.now()
      const session = createGuestSession()
      expect(session.expiresAt).toBe(now + 24 * 60 * 60 * 1000)
    })

    it('persists session to localStorage', () => {
      createGuestSession()
      expect(localStorageMock.setItem).toHaveBeenCalledWith(
        'guest_session',
        expect.any(String)
      )
    })
  })

  // ─── getGuestSession ──────────────────────────────────────────

  describe('getGuestSession', () => {
    it('returns existing session from localStorage', () => {
      const original = createGuestSession()
      const retrieved = getGuestSession()
      expect(retrieved.id).toBe(original.id)
    })

    it('creates a new session if none exists', () => {
      const session = getGuestSession()
      expect(session).toHaveProperty('id')
      expect(session.cartItems).toEqual([])
    })

    it('creates a new session if stored session has expired', () => {
      const session = createGuestSession()
      const originalId = session.id

      // Advance time past expiry
      vi.advanceTimersByTime(25 * 60 * 60 * 1000) // 25 hours

      const retrieved = getGuestSession()
      expect(retrieved.id).not.toBe(originalId)
    })

    it('returns existing session if not expired', () => {
      const session = createGuestSession()
      const originalId = session.id

      // Advance time but not past expiry
      vi.advanceTimersByTime(12 * 60 * 60 * 1000) // 12 hours

      const retrieved = getGuestSession()
      expect(retrieved.id).toBe(originalId)
    })

    it('creates new session if stored JSON is corrupted', () => {
      localStorageMock.setItem('guest_session', 'not-valid-json{{{')
      const session = getGuestSession()
      expect(session).toHaveProperty('id')
      expect(session.cartItems).toEqual([])
    })
  })

  // ─── addToGuestCart ────────────────────────────────────────────

  describe('addToGuestCart', () => {
    it('adds a new item to empty cart', () => {
      const session = addToGuestCart('prod-1', 2, 29.99)
      expect(session.cartItems).toHaveLength(1)
      expect(session.cartItems[0]).toEqual({
        productId: 'prod-1',
        quantity: 2,
        price: 29.99,
      })
    })

    it('increments quantity for existing product', () => {
      addToGuestCart('prod-1', 2, 29.99)
      const session = addToGuestCart('prod-1', 3, 29.99)
      expect(session.cartItems).toHaveLength(1)
      expect(session.cartItems[0].quantity).toBe(5)
    })

    it('adds different products separately', () => {
      addToGuestCart('prod-1', 1, 10.00)
      const session = addToGuestCart('prod-2', 2, 20.00)
      expect(session.cartItems).toHaveLength(2)
    })

    it('persists changes to localStorage', () => {
      addToGuestCart('prod-1', 1, 10.00)
      const stored = JSON.parse(localStorageMock.getItem('guest_session')!)
      expect(stored.cartItems).toHaveLength(1)
    })
  })

  // ─── removeFromGuestCart ───────────────────────────────────────

  describe('removeFromGuestCart', () => {
    it('removes an existing item', () => {
      addToGuestCart('prod-1', 2, 29.99)
      addToGuestCart('prod-2', 1, 19.99)
      const session = removeFromGuestCart('prod-1')
      expect(session.cartItems).toHaveLength(1)
      expect(session.cartItems[0].productId).toBe('prod-2')
    })

    it('does nothing if product not in cart', () => {
      addToGuestCart('prod-1', 2, 29.99)
      const session = removeFromGuestCart('nonexistent')
      expect(session.cartItems).toHaveLength(1)
    })

    it('results in empty cart when removing last item', () => {
      addToGuestCart('prod-1', 1, 10.00)
      const session = removeFromGuestCart('prod-1')
      expect(session.cartItems).toHaveLength(0)
    })
  })

  // ─── updateGuestCartQuantity ───────────────────────────────────

  describe('updateGuestCartQuantity', () => {
    it('updates quantity for existing item', () => {
      addToGuestCart('prod-1', 2, 29.99)
      const session = updateGuestCartQuantity('prod-1', 5)
      expect(session.cartItems[0].quantity).toBe(5)
    })

    it('removes item when quantity is set to 0', () => {
      addToGuestCart('prod-1', 2, 29.99)
      const session = updateGuestCartQuantity('prod-1', 0)
      expect(session.cartItems).toHaveLength(0)
    })

    it('removes item when quantity is negative', () => {
      addToGuestCart('prod-1', 2, 29.99)
      const session = updateGuestCartQuantity('prod-1', -1)
      expect(session.cartItems).toHaveLength(0)
    })

    it('does not add item if product does not exist in cart', () => {
      addToGuestCart('prod-1', 2, 29.99)
      const session = updateGuestCartQuantity('nonexistent', 5)
      expect(session.cartItems).toHaveLength(1)
      expect(session.cartItems[0].productId).toBe('prod-1')
    })
  })

  // ─── getGuestCartTotal ─────────────────────────────────────────

  describe('getGuestCartTotal', () => {
    it('returns 0 for empty cart', () => {
      createGuestSession()
      expect(getGuestCartTotal()).toBe(0)
    })

    it('calculates total for single item', () => {
      addToGuestCart('prod-1', 3, 10.00)
      expect(getGuestCartTotal()).toBe(30.00)
    })

    it('calculates total for multiple items', () => {
      addToGuestCart('prod-1', 2, 10.00)
      addToGuestCart('prod-2', 1, 25.50)
      expect(getGuestCartTotal()).toBeCloseTo(45.50)
    })

    it('handles fractional prices correctly', () => {
      addToGuestCart('prod-1', 1, 9.99)
      addToGuestCart('prod-2', 1, 14.99)
      expect(getGuestCartTotal()).toBeCloseTo(24.98)
    })
  })

  // ─── clearGuestSession ─────────────────────────────────────────

  describe('clearGuestSession', () => {
    it('removes session from localStorage', () => {
      createGuestSession()
      clearGuestSession()
      expect(localStorageMock.removeItem).toHaveBeenCalledWith('guest_session')
    })

    it('after clear, getGuestSession creates a new one', () => {
      const original = createGuestSession()
      clearGuestSession()
      const newSession = getGuestSession()
      expect(newSession.id).not.toBe(original.id)
    })
  })

  // ─── setCheckoutStep ───────────────────────────────────────────

  describe('setCheckoutStep', () => {
    it('updates the checkout step', () => {
      createGuestSession()
      const session = setCheckoutStep(3)
      expect(session.checkoutStep).toBe(3)
    })

    it('persists the step to localStorage', () => {
      createGuestSession()
      setCheckoutStep(2)
      const stored = JSON.parse(localStorageMock.getItem('guest_session')!)
      expect(stored.checkoutStep).toBe(2)
    })

    it('allows setting step to 0', () => {
      createGuestSession()
      setCheckoutStep(3)
      const session = setCheckoutStep(0)
      expect(session.checkoutStep).toBe(0)
    })
  })

  // ─── isSessionValid ────────────────────────────────────────────

  describe('isSessionValid', () => {
    it('returns true for a non-expired session', () => {
      createGuestSession()
      expect(isSessionValid()).toBe(true)
    })

    it('returns false when no session exists', () => {
      expect(isSessionValid()).toBe(false)
    })

    it('returns false for an expired session', () => {
      createGuestSession()
      vi.advanceTimersByTime(25 * 60 * 60 * 1000)
      expect(isSessionValid()).toBe(false)
    })

    it('returns false for corrupted session data', () => {
      localStorageMock.setItem('guest_session', '{broken json')
      expect(isSessionValid()).toBe(false)
    })

    it('returns true at exactly the expiry boundary', () => {
      createGuestSession()
      // Advance to exactly 24 hours — expiresAt = now + 24h, check is Date.now() <= expiresAt
      vi.advanceTimersByTime(24 * 60 * 60 * 1000)
      expect(isSessionValid()).toBe(true)
    })

    it('returns false 1ms after expiry', () => {
      createGuestSession()
      vi.advanceTimersByTime(24 * 60 * 60 * 1000 + 1)
      expect(isSessionValid()).toBe(false)
    })
  })
})

import React from 'react'
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { CheckoutForm } from '@/src/components/CheckoutForm'
import { CartProvider, useCart } from '@/src/context/CartContext'
import { Elements } from '@stripe/react-stripe-js'
import { getStripe } from '@/src/lib/stripe'
import { validateCheckoutForm } from '@/src/lib/validation'

// Mock useRouter
vi.mock('next/navigation', () => ({
  useRouter: () => ({
    push: vi.fn(),
  }),
}))

// Mock fetch
global.fetch = vi.fn()

// Helper component to populate cart
function CheckoutFormWithCart() {
  const { dispatch } = useCart()

  // Add item to cart on mount
  React.useEffect(() => {
    dispatch({
      type: 'ADD_ITEM',
      payload: {
        id: '1',
        name: 'Test Product',
        price: 99.99,
        image: 'https://example.com/image.jpg',
      },
    })
  }, [dispatch])

  return <CheckoutForm />
}

const renderCheckoutForm = () => {
  return render(
    <CartProvider>
      <Elements stripe={getStripe()}>
        <CheckoutFormWithCart />
      </Elements>
    </CartProvider>
  )
}

describe('CheckoutForm', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    localStorage.clear()
  })

  it('should render form fields', () => {
    renderCheckoutForm()

    expect(screen.getByLabelText(/full name/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/email address/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/street address/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/zip code/i)).toBeInTheDocument()
  })

  it('should render GDPR consent checkbox', () => {
    renderCheckoutForm()

    const checkbox = screen.getByRole('checkbox')
    expect(checkbox).toBeInTheDocument()
  })

  it('should have accessible GDPR checkbox with aria-describedby when there are errors', () => {
    renderCheckoutForm()

    const checkbox = screen.getByRole('checkbox', { name: /consent/i })
    // Initially no aria-describedby since there are no errors
    expect(checkbox.getAttribute('aria-describedby')).toBeNull()
  })

  it('should accept valid zip codes in multiple formats', async () => {
    renderCheckoutForm()

    const zipInput = screen.getByLabelText(/zip code/i) as HTMLInputElement

    // Test 5-digit format
    await userEvent.clear(zipInput)
    await userEvent.type(zipInput, '12345')
    expect(zipInput.value).toBe('12345')

    // Test extended format
    await userEvent.clear(zipInput)
    await userEvent.type(zipInput, '12345-6789')
    expect(zipInput.value).toBe('12345-6789')
  })

  it('should update form fields on user input', async () => {
    renderCheckoutForm()

    const nameInput = screen.getByLabelText(/full name/i) as HTMLInputElement
    const emailInput = screen.getByLabelText(/email address/i) as HTMLInputElement

    await userEvent.type(nameInput, 'John Doe')
    expect(nameInput.value).toBe('John Doe')

    await userEvent.type(emailInput, 'john@example.com')
    expect(emailInput.value).toBe('john@example.com')
  })
})

describe('validateCheckoutForm', () => {
  it('should accept a valid complete form', () => {
    const validForm = {
      name: 'John Doe',
      email: 'john@example.com',
      address: '123 Main Street',
      zipCode: '12345',
      gdprConsent: true,
    }
    const errors = validateCheckoutForm(validForm)
    expect(Object.keys(errors).length).toBe(0)
  })

  it('should validate empty name', () => {
    const form = {
      name: '',
      email: 'john@example.com',
      address: '123 Main Street',
      zipCode: '12345',
      gdprConsent: true,
    }
    const errors = validateCheckoutForm(form)
    expect(errors.name).toBeDefined()
    expect(errors.name).toBe('Name is required')
  })

  it('should validate invalid email', () => {
    const form = {
      name: 'John Doe',
      email: 'invalid',
      address: '123 Main Street',
      zipCode: '12345',
      gdprConsent: true,
    }
    const errors = validateCheckoutForm(form)
    expect(errors.email).toBeDefined()
    expect(errors.email).toContain('valid email')
  })

  it('should validate short address', () => {
    const form = {
      name: 'John Doe',
      email: 'john@example.com',
      address: 'St',
      zipCode: '12345',
      gdprConsent: true,
    }
    const errors = validateCheckoutForm(form)
    expect(errors.address).toBeDefined()
    expect(errors.address).toContain('complete address')
  })

  it('should validate invalid zip code', () => {
    const form = {
      name: 'John Doe',
      email: 'john@example.com',
      address: '123 Main Street',
      zipCode: 'ABCDE',
      gdprConsent: true,
    }
    const errors = validateCheckoutForm(form)
    expect(errors.zipCode).toBeDefined()
    expect(errors.zipCode).toContain('valid zip code')
  })

  it('should validate GDPR consent requirement', () => {
    const form = {
      name: 'John Doe',
      email: 'john@example.com',
      address: '123 Main Street',
      zipCode: '12345',
      gdprConsent: false,
    }
    const errors = validateCheckoutForm(form)
    expect(errors.gdprConsent).toBeDefined()
    expect(errors.gdprConsent).toContain('GDPR')
  })

  it('should catch multiple validation errors', () => {
    const form = {
      name: 'A',
      email: 'bad',
      address: 'x',
      zipCode: '123',
      gdprConsent: false,
    }
    const errors = validateCheckoutForm(form)
    expect(Object.keys(errors).length).toBeGreaterThanOrEqual(4)
    expect(errors.name).toBeDefined()
    expect(errors.email).toBeDefined()
    expect(errors.address).toBeDefined()
    expect(errors.zipCode).toBeDefined()
  })
})

// Form validation logic extracted for testability
// This module contains all validation rules for the checkout form

export interface FormData {
  name: string
  email: string
  address: string
  zipCode: string
  gdprConsent: boolean
}

export interface FormErrors {
  [key: string]: string
}

/**
 * Validates a name field
 * Rules: Required, non-empty, at least 2 characters
 */
export const validateName = (name: string): string | null => {
  if (!name || name.trim().length === 0) {
    return 'Name is required'
  }
  if (name.length < 2) {
    return 'Name must be at least 2 characters'
  }
  return null
}

/**
 * Validates an email field
 * Rules: Required, valid email format
 */
export const validateEmail = (email: string): string | null => {
  if (!email) {
    return 'Email is required'
  }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return 'Please enter a valid email address'
  }
  return null
}

/**
 * Validates an address field
 * Rules: Required, non-empty, at least 5 characters
 */
export const validateAddress = (address: string): string | null => {
  if (!address || address.trim().length === 0) {
    return 'Address is required'
  }
  if (address.length < 5) {
    return 'Please enter a complete address'
  }
  return null
}

/**
 * Validates a zip code field
 * Rules: Required, valid US zip code format (12345 or 12345-6789)
 */
export const validateZipCode = (zipCode: string): string | null => {
  if (!zipCode || zipCode.trim().length === 0) {
    return 'Zip code is required'
  }
  if (!/^\d{5}(?:-\d{4})?$/.test(zipCode.replace(/\s/g, ''))) {
    return 'Please enter a valid zip code'
  }
  return null
}

/**
 * Validates GDPR consent
 * Rules: Must be checked (true)
 */
export const validateGdprConsent = (gdprConsent: boolean): string | null => {
  if (!gdprConsent) {
    return 'You must consent to the GDPR policy to continue'
  }
  return null
}

/**
 * Validates the entire form
 * Returns an object with field-level error messages
 * Empty object means form is valid
 */
export const validateCheckoutForm = (formData: FormData): FormErrors => {
  const newErrors: FormErrors = {}

  const nameError = validateName(formData.name)
  if (nameError) {
    newErrors.name = nameError
  }

  const emailError = validateEmail(formData.email)
  if (emailError) {
    newErrors.email = emailError
  }

  const addressError = validateAddress(formData.address)
  if (addressError) {
    newErrors.address = addressError
  }

  const zipCodeError = validateZipCode(formData.zipCode)
  if (zipCodeError) {
    newErrors.zipCode = zipCodeError
  }

  const gdprError = validateGdprConsent(formData.gdprConsent)
  if (gdprError) {
    newErrors.gdprConsent = gdprError
  }

  return newErrors
}

/**
 * Validates payment request input
 * Rules: Amount must be positive
 */
export const validatePaymentAmount = (amount: number): string | null => {
  if (!amount || amount <= 0) {
    return 'Invalid payment amount'
  }
  return null
}
